{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Bacterial co-infection and secondary infection in patients with COVID19: a living rapid review and meta-analysis",
      "reason": "The title explicitly identifies the report as a 'systematic review' (and meta-analysis)."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Bacterial co-infection and secondary infection in patients with COVID19",
      "reason": "The title conveys the population (patients with COVID-19) and exposure (bacterial co-infection and secondary infection), indicating the review question."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "a living rapid review and meta-analysis",
      "reason": "The title includes supplementary information on review design (rapid review), analysis method (meta-analysis), and living-review status."
    }
  ],
  "confidence": 96
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The prevalence, incidence and characteristics of bacterial infection in patients infected with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2) is not well understood and has been raised as an important knowledge gap [6,7].",
      "reason": "The Introduction describes existing knowledge (co-infection in influenza) and explicitly identifies the uncertainty/knowledge gap for SARS-CoV-2."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Understanding the proportion of COVID-19 patients with acute respiratory bacterial co-infection, and the culprit pathogens, is crucial for treating patients with COVID-19 and to help ensure responsible use of antibiotics and to minimize negative consequences of overuse [6].",
      "reason": "The Introduction explains the importance of the review for clinical care and antibiotic stewardship, and states the review's purpose."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "To our knowledge, this is the fi rst living meta-analysis and systematic review focusing on bacterial co-infections in patients hospitalized for COVID-19",
      "reason": "The Introduction does not cite prior similar reviews, but the Discussion claims this is the first such review and compares with a recent systematic review [39], partially explaining the need for the current review. The claim appears in Discussion rather than Introduction, so only partial."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of prevalence of bacterial co-infection, not of intervention effects, so no mechanism of action description is required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Not a review of complex interventions; no logic model is applicable to a prevalence review."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "We conducted a rapid systematic review guided by recommendations from the Cochrane Rapid Reviews Methods Group [10] to determine the prevalence of respiratory bacterial infections among individuals with confirmed active COVID-19 infection.",
      "reason": "The objective is explicitly stated in the Methods (and echoed in the abstract's Aims: 'To determine the prevalence of bacterial co-infection (at presentation) and secondary infection (after presentation) in patients with COVID-19'), clearly defining the review question."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of prevalence (etiology/epidemiology), not of intervention effects; PICO-style planned comparisons do not apply. The objective and eligibility criteria are reported in text_5 and text_3."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "We included studies of humans with laboratory-con fi rmed SARS-CoV-2 infection across all healthcare settings (i.e. hospital, community, long-term care) and age groups (paediatric and adult patients). Bacterial infection was de fi ned as an acute infection including either (a) co-infection on presentation, or (b) secondary infection emerging during the course of illness or hospital stay. Cases where bacteria were detected in an isolate not from a respiratory tract or blood culture sample were excluded. We included randomized controlled trials, cohort studies and case series with more than 10 patients, but excluded reviews, editorials, letters and case studies.",
      "reason": "The Methods section comprehensively specifies eligibility characteristics: population (humans with laboratory-confirmed SARS-CoV-2), settings (all healthcare settings), age groups, condition definitions (co-infection vs secondary infection, specimen source restrictions), and eligible study designs (RCTs, cohorts, case series >10 patients) with explicit design exclusions. Follow-up requirements are not stated but are not relevant to this prevalence-focused question."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "We performed a systematic search of MEDLINE, OVID Epub and EMBASE databases for published literature in the English language from January 1, 2019 to April 16, 2020 with assistance from a medical library information specialist.",
      "reason": "Report characteristic restrictions are specified: publication status (published literature only), language (English only), and date range restricting dissemination to January 1, 2019 through April 16, 2020."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_10",
      "quote": "The main reason for study exclusion was the lack of reporting of bacterial co-infection or bacterial secondary infection data (Fig. 1).",
      "reason": "The review excluded 130 studies for 'bacterial infection data not available or incomplete' (per Fig. 1 flow diagram), but never distinguishes exclusion because bacterial infection outcomes were not measured from exclusion because measured outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Seven studies exclusively reported secondary bacterial infections, the remaining 17 studies were categorized as reporting bacterial co-infection. ... When strati fi ed by patient population (an estimate of COVID-19 illness severity), bacterial infection ranged from 5.9% (95%CI 3.8 e 8.0%) in all hospitalized patients to 8.1% in critically ill patients (95%CI 2.3 e 13.8)",
      "reason": "Synthesis groups are specified and linked to the review objective of estimating prevalence of bacterial infection: studies grouped as co-infection vs secondary infection (matching the definitions in text_5 and shown as 'Category = Co-infection' and 'Category = Secondary' in the Fig. 2 forest plot), plus stratification by patient population/severity (all hospitalized vs critically ill) and sensitivity analyses by testing method."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Notable eligibility restrictions are imposed (English language only, case series limited to >10 patients, specimens restricted to respiratory tract or blood culture, exclusion of chronic co-infection/non-bacterial pathogens) but no rationales for these restrictions are provided anywhere in the retrieved evidence; the rapid-review justification in text_5 relates to the methodology choice, not the eligibility restrictions."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_7",
  "elements": [
    {
      "element_id": "prisma_2020_7_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "We performed a systematic search of MEDLINE, OVID Epub and EMBASE databases for published literature in the English language from January 1, 2019 to April 16, 2020 with assistance from a medical library information specialist. The search was structured to include COVID-19 terms and co-infection or bacterial infection or respiratory infection or epidemiology or descriptive cohort study terms. The complete search strategy is described in the Appendix.",
      "reason": "Databases searched, concept blocks, and limits are summarized in the text and the full strategy is deferred to a supplementary Appendix; the Appendix content itself is not in the retrieved evidence (text_18 only provides a DOI link to supplementary data), so the complete line-by-line strategy as actually run for each database cannot be verified."
    },
    {
      "element_id": "prisma_2020_7_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "for published literature in the English language from January 1, 2019 to April 16, 2020",
      "reason": "Language (English) and date limits (Jan 1, 2019 to Apr 16, 2020) are described, but no justification linking these limits to the eligibility criteria is provided; the eligibility criteria in text_5 (study designs, population, infection definitions) do not reference language or date restrictions."
    },
    {
      "element_id": "prisma_2020_7_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence indicates that published search approaches or filters (e.g., validated subject filters) were used or adapted; the search was built with an information specialist but no published filter is cited."
    },
    {
      "element_id": "prisma_2020_7_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No natural-language processing or text-analysis tools for identifying or refining search terms are mentioned anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No tools for translating search strings between databases/sources are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No validation of the search strategy (process or validation studies) is described in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_7_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "An information specialist assisted in formulating and executing the search (text_6, text_16), but no formal peer review of the search strategy (e.g., PRESS) is reported."
    },
    {
      "element_id": "prisma_2020_7_e8",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The search was structured to include COVID-19 terms and co-infection or bacterial infection or respiratory infection or epidemiology or descriptive cohort study terms.",
      "reason": "The final conceptual structure (COVID-19 terms combined with infection, epidemiology, and study-design term blocks, which is not a PICO framework) is described, but the explorations or process used to develop the term sets are not described beyond noting assistance from a medical library information specialist."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_8",
  "elements": [
    {
      "element_id": "prisma_2020_8_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "All titles and abstracts were independently screened by two authors (BL, VL) to determine whether studies met the inclusion criteria; all full-text studies meeting these criteria were then reviewed by two authors (BL and MS or SR) for fi nal inclusion in the rapid review.",
      "reason": "The number of reviewers is explicitly reported for both screening stages: two authors (BL, VL) screened titles/abstracts, and two authors (BL and MS or SR) reviewed full texts."
    },
    {
      "element_id": "prisma_2020_8_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "All titles and abstracts were independently screened by two authors (BL, VL) to determine whether studies met the inclusion criteria; all full-text studies meeting these criteria were then reviewed by two authors (BL and MS or SR) for fi nal inclusion in the rapid review.",
      "reason": "Independent screening is explicitly stated for the title/abstract stage ('independently screened by two authors'). For the full-text stage, dual review by two authors and a consensus process are described, which implies but does not explicitly state that reviewers worked independently."
    },
    {
      "element_id": "prisma_2020_8_e3",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Disagreements that could not be resolved via consensus were reviewed independently by an additional author.",
      "reason": "The disagreement resolution process is described: consensus between reviewers first, with unresolved disagreements referred to an additional independent author."
    },
    {
      "element_id": "prisma_2020_8_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "we excluded studies that did not report data on bacterial infection or exclusively reported data on chronic co-infection or non-bacterial pathogens",
      "reason": "No process for obtaining or confirming eligibility information from study investigators is reported anywhere in the retrieved evidence. Eligibility was determined solely from published reporting, with studies lacking the required data simply excluded; there is no indication investigator contact was needed or performed."
    },
    {
      "element_id": "prisma_2020_8_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "We performed a systematic search of MEDLINE, OVID Epub and EMBASE databases for published literature in the English language from January 1, 2019 to April 16, 2020",
      "reason": "The search was restricted to English-language publications, so no translation of abstracts or full articles for eligibility assessment was required; no translation methods are reported."
    },
    {
      "element_id": "prisma_2020_8_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "The results of the search were imported into Covidence (Covidence, Melbourne, Australia), an online software tool for systematic reviews. Duplicate records were removed using Covidence.",
      "reason": "No automation tools for the selection process (e.g., machine-learning or text-mining tools assisting screening decisions) are reported. Covidence served only as a review-management platform for record import and duplicate removal; all eligibility screening was performed manually by two reviewers."
    },
    {
      "element_id": "prisma_2020_8_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No externally derived classifiers are mentioned anywhere in the retrieved evidence; screening was conducted manually by named reviewers, so this reporting requirement does not apply."
    },
    {
      "element_id": "prisma_2020_8_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No internally derived classifiers or machine-learning training/validation are mentioned in the retrieved evidence; study selection was manual."
    },
    {
      "element_id": "prisma_2020_8_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No machine-learning prioritisation tools or screening stopping/prioritisation rules are reported in the retrieved evidence; all records were screened by human reviewers."
    },
    {
      "element_id": "prisma_2020_8_e10",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No crowdsourcing platforms are mentioned in the retrieved evidence; screening was performed by the authors themselves."
    },
    {
      "element_id": "prisma_2020_8_e11",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No previously screened datasets used to eliminate records are reported; records came from a fresh MEDLINE, OVID Epub and EMBASE search, with only duplicates removed via Covidence (576 duplicates in the flow diagram, not from a prior screening dataset)."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_9",
  "elements": [
    {
      "element_id": "prisma_2020_9_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Two authors performed data extraction from included studies using a spreadsheet, and cross-checked for accuracy and completeness (DW, BL).",
      "reason": "The Data Extraction section explicitly states that two authors collected data from each included study."
    },
    {
      "element_id": "prisma_2020_9_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Two authors performed data extraction from included studies using a spreadsheet, and cross-checked for accuracy and completeness (DW, BL).",
      "reason": "Dual extraction by two authors with cross-checking is reported, but the manuscript does not explicitly state that the two authors extracted data independently (i.e., in duplicate before comparison); 'cross-checked' implies verification but not clearly independent extraction."
    },
    {
      "element_id": "prisma_2020_9_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The Data Extraction section (text_8) describes cross-checking but no process for resolving disagreements between data extractors. The only disagreement-resolution process described (text_7: unresolved disagreements reviewed by an additional author) is explicitly within the Study Selection section and pertains to inclusion decisions, not data collection."
    },
    {
      "element_id": "prisma_2020_9_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence that study investigators were contacted or that any data were obtained or confirmed from investigators; data were extracted from published reports using a spreadsheet (text_8), so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_9_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "Two authors performed data extraction from included studies using a spreadsheet",
      "reason": "Data collection was performed manually using a spreadsheet; no automation tools were used for data extraction (Covidence, per text_6, was used only to import search results and remove duplicates during study selection), so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_9_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "published literature in the English language from January 1, 2019 to April 16, 2020",
      "reason": "The review was restricted to English-language publications, so translation of articles for data collection was not required; no translation methods were needed or reported, making this conditional requirement inapplicable."
    },
    {
      "element_id": "prisma_2020_9_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence that any data were extracted from figures in the included reports; the variables listed as extracted (text_8) make no mention of figure-based extraction or associated software, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_9_e8",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "To avoid duplication of patient data, each study was captured only once, reporting either co-infection or secondary infection data, whichever component was larger.",
      "reason": "A decision rule for avoiding duplicate patient data and selecting which infection-type data to capture is described (text_9), and overlapping datasets were flagged (text_8: 'Studies potentially describing overlapping data were noted'); however, explicit rules for choosing among multiple reports of the same study and for resolving inconsistencies between reports or within reports are not fully described."
    }
  ],
  "confidence": 85
}

