{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The following variables were extracted: country of study, start and end date of study, healthcare site name(s), study design (retrospective versus prospective), healthcare setting, sample size, age group, patient population, mean or median age, proportion of female patients, disease severity, proportion of patients requiring mechanical ventilation, proportion of patients that were smokers, reported comorbidities (i.e., chronic obstructive pulmonary disease, cardiovascular disease, hypertension), bacteriological testing methods, patients with acute respiratory co-infection, proportion of patients with secondary bacterial infection, respiratory organisms identi fi ed and their proportions, bacterial susceptibility, viral testing methods, proportion of patients receiving antibiotics and class of antibiotic.",
